oxy_webhelp_navlinks = {"tocId-d39307e36397":{"topics":[{"title":"Key features for protecting MongoDB logical backup and recovery","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> provides unified data management, automated global data         protection, backup and recovery options, and advanced security features to protect your         MongoDB logical backup and recovery sources.<\/p>","href":"mongodb\/logical_backup_recv_mdb_protection.html","attributes":{"data-id":"logical_backup_recv_mdb_protection"},"menu":{"hasChildren":false},"tocID":"logical_backup_recv_mdb_protection-d39307e36401","topics":[]},{"title":"Plan your MongoDB logical backup and recovery protection","shortdesc":"<p class=\"shortdesc\">Before you set up MongoDB logical backup and recovery, plan user and access         management for your <span class=\"ph\">RSC<\/span> users, and review the permissions, deployment scale         thresholds, and limitations that apply to your MongoDB environment.<\/p>","href":"mongodb\/mdb_logic_br_plan_protection.html","attributes":{"data-id":"mdb_logic_br_plan_protection"},"menu":{"hasChildren":false},"tocID":"mdb_logic_br_plan_protection-d39307e36414","next":"mdb_logic_br_plan_protection-d39307e36414"},{"title":"Set up MongoDB source for logical backup and recovery","shortdesc":"<p class=\"shortdesc\">Set up a MongoDB source for logical backup and recovery by meeting the prerequisites,         adding the MongoDB hosts, and adding the MongoDB source to <span class=\"ph\">RSC<\/span>.<\/p>","href":"mongodb\/mdb_logic_br_set_up_source.html","attributes":{"data-id":"mdb_logic_br_set_up_source"},"menu":{"hasChildren":false},"tocID":"mdb_logic_br_set_up_source-d39307e36534","next":"mdb_logic_br_set_up_source-d39307e36534"}]}};